const D = { density:.5, weave:.4, energy:.6, speed:1, scale:1, hue:210, x:.5, y:.5, families:3, tilt:.5, mismatch:.5, style:'opart', act:'rotate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W=width, H=height, u=Math.min(W,H), TAU=Math.PI*2;
const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat) S.lastBeat=K.beat; S.lastBeat=K.beat;

const st=P.style, act=P.act;
const F=Math.max(2,Math.min(4,Math.round(P.families)));

// seeded per-family layout (rebuild on seed or family-count change)
if(S.seedUsed!==P.seed || S.F!==F){
  S.seedUsed=P.seed; S.F=F;
  const fam=[];
  for(let k=0;k<F;k++){
    fam.push({
      base:(fr(k*5+1)-0.5)*0.30,
      rate:(0.5+fr(k*5+2)*1.1)*(fr(k*5+5)<.5?-1:1),
      pr:0.86+fr(k*5+3)*0.28,
      wph:fr(k*5+4)*TAU,
      wf:1.3+fr(k*5+6)*1.9,
      slide:(fr(k*5+7)-0.5)*2,
      mx:(fr(k*5+8)-0.5)*0.022,
      my:(fr(k*5+9)-0.5)*0.022
    });
  }
  S.fam=fam;
}
const fam=S.fam;

const dens=cl(P.density,0,1), wv=cl(P.weave,0,1), en=cl(P.energy,0,1);
const spd=cl(P.speed,0,4), sc=cl(P.scale,.4,3), hue=md(P.hue,360);
const AL=cl(P.alpha,0,100), alF=AL/100;
const sec=K.section||0, intens=0.55+0.6*(K.intensity!=null?K.intensity:.6);
const dr=0.30+spd;

// anchor pulled toward center so the rotating rig always covers the whole frame
const cx=(0.5+(cl(P.x,0,1)-0.5)*0.4)*W, cy=(0.5+(cl(P.y,0,1)-0.5)*0.4)*H;
const R=Math.hypot(W,H)*0.72;

// 1st poke = line count (density) ; 2nd poke = waviness (weave)
const nAcross=14+dens*70;
let period=(u/nAcross)/sc;
const SEG=1+Math.round(wv*13);
const segV=SEG+1;
const BUD=1700;                                 // total-vertex budget (worst case stays < 2000 cap)
const periodFloor=(2*R*F*segV)/BUD;             // coarsen if fine+wavy+many families would blow budget
period=Math.max(period, periodFloor);
const waveAmp=wv*period*3.0;                     // curvature amplitude, proportional to spacing
const waveK=TAU/u;
const nL=Math.min(260, Math.ceil(R/period));

// motion floor — everything on K.t (never re-phases); dr floor keeps it alive at speed 0.
// A big frame turns any tiny rotation into a large tangential line-shift at mid-radius, and
// high-contrast gratings strobe on a half-period shift, so total 8s shift is budgeted small.
// The moire FRINGE is far more angle-sensitive than the lines, so it still sweeps visibly.
// mot: straight+fine gratings strobe hardest, so slow them; wavy fields may drift a little faster.
const mot=0.5+0.7*wv;
const baseRot=md(P.tilt*TAU + K.t*0.0016*dr*mot, TAU);
let breathAmp=0.03, rateAmp=0.0016*mot, slideAmp=0.05*mot;
if(act==='breathe'){ breathAmp=0.08; rateAmp=0.0013*mot; }
else if(act==='slide'){ breathAmp=0.02; rateAmp=0.0011*mot; slideAmp=0.18*mot; }
const breath=0.5+0.5*Math.sin(K.t*0.045*dr + sec*0.6);
const aBloom=(A.lowmid||0)*0.35+(A.rms||0)*0.25, aCon=(A.bass||0)*0.5;

const dutyBase=cl(0.16+en*0.24, .12, .48);
const contrast=cl(intens*(0.5+0.7*en)+aCon, 0, 1.4);
const hueDrift=sec*15;

// palette / ground per style — ground alone holds luminance safely in-gate
const dark=(st==='neon'||st==='thermal'||st==='blueprint');
const gH = st==='opart'?0 : st==='riso'?38 : st==='blueprint'?212 : st==='neon'?258 : 250;
const gS = st==='opart'?0 : st==='riso'?12 : st==='blueprint'?78 : st==='neon'?40 : 40;
const gV = st==='opart'?88 : st==='riso'?90 : st==='blueprint'?15 : st==='neon'?10 : 10;

blendMode(BLEND);
if(AL>=99) background(gH,gS,gV);
else { noStroke(); fill(gH,gS,gV,AL); rect(0,0,W,H); }

const addA=cl(0.60/F*(0.6+contrast*0.6), .05, .45);   // per-family ADD alpha; /F bounds the overlap sum
function heat(m){ return [md(282-262*m,360), 88-34*m, 52+46*m]; }

push();
translate(cx,cy);
strokeCap(ROUND);
noFill();
// ADD glow on dark grounds; opaque BLEND ink on light grounds (Riley-authentic + luminance-floored)
if(dark) blendMode(ADD); else blendMode(BLEND);

for(let k=0;k<F;k++){
  const f=fam[k];
  const spread=cl((0.045+breathAmp*breath+aBloom*0.12), 0.03, 0.5);
  const ang=baseRot + f.base + f.rate*(K.t*rateAmp*dr) + spread*(k-(F-1)/2);
  const pk=period*(1+(f.pr-1)*cl(P.mismatch,0,1)*0.9);
  const off=(K.t*dr*slideAmp*f.slide)%pk;
  const wPh=f.wph + K.t*dr*(0.011+0.016*wv)*(0.6+f.slide*0.5);   // waves undulate gently; scales with weave so wavy many-family fields keep clear motion
  const lw=Math.max(0.65, pk*dutyBase*(dark?0.85:1.0));

  if(st==='opart') stroke(0,0,12, 100*alF);
  else if(st==='riso'){ const rh=md(hue+(k%2)*150+hueDrift,360); stroke(rh,66,54, 90*alF); }
  else if(st==='blueprint') stroke(md(198+hueDrift*0.3,360),52,94, (24+en*24)*alF*(0.7+contrast*0.5));
  else if(st==='neon'){ const nh=md(hue+(k%2)*162+(k>>1)*46+hueDrift,360); stroke(nh,92,96, addA*100*alF); }
  else { const c=heat((k+0.5)/F); stroke(md(c[0]+hueDrift,360),c[1],c[2], addA*100*alF); }

  strokeWeight(lw);
  push();
  if(st==='riso') translate(f.mx*u*breath, f.my*u*breath);   // print misregistration
  rotate(ang);
  for(let i=-nL;i<=nL;i++){
    const x0=i*pk+off;
    if(SEG<=1){ line(x0,-R,x0,R); }
    else {
      beginShape();
      for(let s=0;s<=SEG;s++){
        const yy=-R+(2*R)*s/SEG;
        const x=x0 + waveAmp*Math.sin(yy*waveK*f.wf + wPh);
        vertex(x,yy);
      }
      endShape();
    }
  }
  pop();
}
blendMode(BLEND);
pop();

// audio sparkle on top — few ADD dots, silent during validation
if((A.treble||0)>0.06 && AL>10){
  push(); blendMode(ADD); noStroke();
  const n=Math.min(12, Math.floor(12*A.treble));
  const jb=Math.floor(K.beat*2);
  for(let s=0;s<n;s++){
    const a=fr(s*3.3+jb)*TAU, rr=fr(s*1.7+jb)*u*0.42;
    fill(dark?md(hue+40,360):0, dark?70:0, 100, 46*A.treble*alF);
    circle(cx+Math.cos(a)*rr, cy+Math.sin(a)*rr, u*0.006);
  }
  blendMode(BLEND); pop();
}
